<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$token=(string)($_GET['token']??'');$id=(int)($_GET['invoice']??0);$s=$db->prepare('SELECT s.client_id FROM client_portal_sessions s WHERE s.token_hash=? AND s.expires_at>NOW()');$s->execute([hash('sha256',$token)]);$session=$s->fetch();if(!$session){http_response_code(403);exit('Invalid or expired portal link.');}$q=$db->prepare("SELECT i.*,COALESCE(c.name,l.name) client_name FROM invoices i LEFT JOIN clients c ON c.id=i.client_id LEFT JOIN leads l ON l.id=i.lead_id WHERE i.id=? AND (i.client_id=? OR (i.client_id IS NULL AND i.lead_id=(SELECT lead_id FROM clients WHERE id=?)))");$q->execute([$id,$session['client_id'],$session['client_id']]);$i=$q->fetch();if(!$i){http_response_code(404);exit('Invoice not found.');}$x=$db->prepare('SELECT * FROM invoice_items WHERE invoice_id=? ORDER BY sort_order,id');$x->execute([$id]);$items=$x->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$e($i['invoice_number'])?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><a href="billing.php?token=<?=$e(urlencode($token))?>">← Billing</a><div class="card mt-3"><div class="card-body"><div class="d-flex justify-content-between"><div><h1 class="h3">Invoice <?=$e($i['invoice_number'])?></h1><p><?=$e($i['title'])?></p></div><span class="badge text-bg-dark"><?=$e($i['status'])?></span></div><table class="table"><thead><tr><th>Description</th><th>Qty</th><th>Amount</th></tr></thead><tbody><?php foreach($items as $x):?><tr><td><?=$e($x['description'])?></td><td><?=$e($x['quantity'])?></td><td><?=$e($i['currency'])?> <?=number_format((float)$x['amount'],2)?></td></tr><?php endforeach;?></tbody></table><div class="text-end"><div>Subtotal: <?=$e($i['currency'])?> <?=number_format((float)$i['subtotal'],2)?></div><div>Tax: <?=$e($i['currency'])?> <?=number_format((float)($i['tax']??$i['tax_amount']),2)?></div><h3>Total: <?=$e($i['currency'])?> <?=number_format((float)$i['total'],2)?></h3><div>Paid: <?=$e($i['currency'])?> <?=number_format((float)$i['amount_paid'],2)?></div><h4>Balance: <?=$e($i['currency'])?> <?=number_format((float)$i['balance_due'],2)?></h4></div><?php if((float)$i['balance_due']>0&&$i['status']!=='cancelled'):?><a class="btn btn-primary" href="pay-invoice.php?token=<?=$e(urlencode($token))?>&invoice=<?=$id?>">Pay Now</a><?php endif;?></div></div></main></body></html>